package com.xiahu.reader;
import android.app.*;import android.os.*;import android.content.*;import android.net.Uri;import org.json.*;
public final class RegistrationTest extends Instrumentation{
 @Override public void onCreate(Bundle b){super.onCreate(b);start();}
 @Override public void onStart(){Bundle out=new Bundle();boolean ok=false;try{Intent i=Registration.browserIntent();Uri u=i.getData();if(!Intent.ACTION_VIEW.equals(i.getAction())||!"https".equals(u.getScheme())||!"www.wenku8.net".equals(u.getHost())||!"/register.php".equals(u.getPath()))throw new AssertionError("Official HTTPS registration URL");if(u.getQuery()!=null||u.getUserInfo()!=null||i.getExtras()!=null)throw new AssertionError("No login credentials or cookies passed");if(i.getSelector()==null||!Intent.ACTION_MAIN.equals(i.getSelector().getAction())||!i.getSelector().hasCategory(Intent.CATEGORY_APP_BROWSER))throw new AssertionError("External browser selection required");Intent fallback=Registration.webIntent();if(!Registration.URL.equals(fallback.getDataString())||!fallback.hasCategory(Intent.CATEGORY_BROWSABLE)||fallback.getExtras()!=null)throw new AssertionError("System web-handler fallback preserves safe URL");out.putString("report",new JSONObject().put("passed",true).put("officialRegistrationUrl",true).put("externalBrowserOnly",true).put("systemWebHandlerFallback",true).put("noCredentialsCookiesOrRegistrationApi",true).toString());ok=true;}catch(Throwable e){out.putString("failure",e.toString());}finish(ok?Activity.RESULT_OK:Activity.RESULT_CANCELED,out);}
}
